int main() {
    int LIMIT;
    cin >> LIMIT;                          // nivell 0: LIMIT = 100
    int X = 1;
    while (X < LIMIT) {                    // nivell 1: recórrer els candidats
        int SD = 0;                        // nivell 3: suma dels divisors
        for (int P = 1; P <= X; P++) {
            if (X % P == 0) {
                SD = SD + P;
            }
        }
        if (SD - X == X) {                 // nivell 2: decidir i escriure
