#include <iostream>
using namespace std;

int main() {
    int X;
    cin >> X;
    int SD = 0;
    for (int P = 1; P <= X; P++) {
        if (X % P == 0) {
            SD = SD + P;
        }
    }
    cout << "Suma dels divisors de " << X << ": " << SD << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int LIMIT;
    cin >> LIMIT;
    long long voltesA = 0, voltesB = 0;
    for (int X = 1; X < LIMIT; X++) {
        for (int P = 1; P <= X; P++) voltesA++;       // versió fins a X
        for (int P = 1; P <= X / 2; P++) voltesB++;   // versió fins a X / 2
    }
    cout << "Voltes fins a X:     " << voltesA << endl;
    cout << "Voltes fins a X / 2: " << voltesB << endl;
    return 0;
}
